<?php
require __DIR__.'/bootstrap.php';
use Dilemma\{Arguments,Auth,Connections,Db,DebateActions,Debates,ReadModel,Support,Views};
$a=user_fixture('LiveA');$b=user_fixture('LiveB');$c=user_fixture('LiveC');
$d=debate_fixture($a['actor'],$b['actor'],false);$id=$d['id'];$user=Auth::session($a['session']['token']);
rejects(fn()=>Views::live_debate($id,null,null,0),404,'Anonymous live reader cannot see a private debate');
rejects(fn()=>Views::live_debate($id,Auth::session($c['session']['token']),$c['actor'],0),404,'Unrelated account cannot use live feed');
$empty=Views::live_debate($id,$user,$a['actor'],0);
check($empty['arguments']===[]&&$empty['next_ordinal']===0&&!$empty['has_more'],'Empty feed has a stable zero cursor');
check($empty['can_publish']&&!Views::live_debate($id,Auth::session($b['session']['token']),$b['actor'],0)['can_publish'],'Live publishing state belongs to the authenticated participant');
for($i=1;$i<=22;$i++)Arguments::submit($i%2?$a['actor']:$b['actor'],$id,['revision'=>(int)Debates::row($id)['revision'],'idempotency_key'=>Support::token(),'body'=>'Argument '.$i.': <script>alert("unsafe")</script> & evidence matters.']);
$batch=Views::live_debate($id,$user,$a['actor'],0);
check(count($batch['arguments'])===20&&$batch['next_ordinal']===20&&$batch['has_more'],'Catch-up is bounded to twenty ordered cards');
check(array_column($batch['arguments'],'ordinal')===range(1,20),'Live order matches historical argument order');
check(!str_contains($batch['arguments'][0]['html'],'<script>')&&str_contains($batch['arguments'][0]['html'],'&lt;script&gt;'),'User text remains escaped in server-rendered live cards');
check(str_contains($batch['arguments'][0]['html'],'amend-form')&&!str_contains($batch['arguments'][1]['html'],'amend-form'),'Only own argument receives its clarification form');
$next=Views::live_debate($id,$user,$a['actor'],20);
check(array_column($next['arguments'],'ordinal')===[21,22]&&!$next['has_more'],'Remaining batch crosses the historical page boundary without omissions');
check(Views::live_debate($id,$user,$a['actor'],22)['arguments']===[],'Acknowledged cards are not sent again');
rejects(fn()=>Views::live_debate($id,$user,$a['actor'],23),422,'Future cursor rejected');
DebateActions::apply($b['actor'],$id,['action'=>'consent','revision'=>(int)Debates::row($id)['revision'],'idempotency_key'=>Support::token(),'public_consent'=>true,'position_consent'=>false]);
$public=Views::live_debate($id,null,null,20);
check(count($public['arguments'])===2&&!str_contains($public['arguments'][0]['html'],'<form'),'Public reader receives cards without participant controls');
check(!isset($public['participants'][0]['user_id'])&&!str_contains(Support::json($public),$a['email']),'Feed omits account email and unnecessary participant identifiers');
DebateActions::apply($b['actor'],$id,['action'=>'consent','revision'=>(int)Debates::row($id)['revision'],'idempotency_key'=>Support::token(),'public_consent'=>false,'position_consent'=>false]);
rejects(fn()=>Views::live_debate($id,null,null,22),404,'Withdrawal of publication consent stops subsequent public polls');
$grant=actor_token($a['actor'],false,$id);Connections::revoke($a['actor'],$grant['id']);
rejects(fn()=>ReadModel::live_debate($id,$grant['actor'],0),401,'Previously resolved revoked connection cannot read live data');
$html=Views::page('/debate/'.$id,$user,$a['actor']);
check(str_contains($html,'data-live-after="22"')&&str_contains($html,'data-retry-live')&&!str_contains($html,'data-refresh-debate'),'Rendered page starts at current total and retries without reload');
Db::run('UPDATE debates SET hidden=1 WHERE id=?',[$id]);
rejects(fn()=>Views::live_debate($id,null,null,0),404,'Hidden debate does not leak via feed');
echo 'SUCCESS: '.$checks." live feed checks.\n";
